def transform(grid):
    a=[r[:] for r in grid]
    H,W=len(a),len(a[0])
    bg=max(set(x for r in a for x in r),key=lambda x:sum(row.count(x) for row in a))
    for y in range(H):
        for x in range(1,W-1):
            if grid[y][x]==bg: continue
            choices=[]
            for dx in (-1,1):
                xx=x+dx
                while 0<=xx<W and grid[y][xx]==bg: xx+=dx
                if 0<=xx<W and xx in (0,W-1) and grid[y][xx]!=bg: choices.append((abs(xx-x),dx))
            if choices:
                _,dx=min(choices); xx=x+dx
                while 0<=xx<W and grid[y][xx]==bg:
                    a[y][xx]=grid[y][x]; xx+=dx
                a[y][x]=4
    return a

